import json,collections,base64,zlib,csv
import run_change_point as d
import select_change_point as p
import report_comparative_benchmark as common
import numpy as np
B=d.B;O=d.O;METHODS=['A0','A1','A2','A3','SVM-X default','SVM-X matched','SVM-CP default','SVM-CP matched']
FILTERS={**common.FILTERS,'weak_steps':lambda x:x['origin']=='SENSOR_CONTROL' and x['kind']=='step' and abs(x['magnitude'])<.8,'strong_steps':lambda x:x['origin']=='SENSOR_CONTROL' and x['kind']=='step' and abs(x['magnitude'])>=.8,'short_pulses':lambda x:x['origin']=='SENSOR_CONTROL' and x['kind']=='pulse' and x['duration_ms']<=250,'long_pulses':lambda x:x['origin']=='SENSOR_CONTROL' and x['kind']=='pulse' and x['duration_ms']>250,'slow_drift':lambda x:x['origin']=='SENSOR_CONTROL' and x['kind']=='ramp',**{domain+'_only':lambda x,domain=domain:x['origin']=='SENSOR_CONTROL' and x['domain']==domain for domain in ['A','B','C']},'global_common':lambda x:x['origin']=='SENSOR_CONTROL' and x['domain']=='ABC'}
def stats(rr):
 s=common.stats(rr);s['wrong_confident_fault_runs']=p.wrong_fault(rr);s['wrong_confident_fault_samples']=sum(x['wrong_localized_runtime_samples'] for x in rr if x['injected']);s['first_accuracy_including_unknown']=s['correct_localizations']/s['detected'] if s['detected'] else None
 if s['benign_runs']:s['benign_ci_low'],s['benign_ci_high']=d.h.wilson(s['benign_false_alarms'],s['benign_runs'])
 else:s['benign_ci_low']=s['benign_ci_high']=None
 if rr and rr[0]['method'].startswith('SVM'):
  for k in list(s):
   if any(t in k for t in ['localiz','unknown','runtime_','wrong_confident','first_accuracy']):s[k]=None
  s['localization_provided']=False
 return s

def generate():
 d.verify();parts={part:json.loads((B/(part+'_evaluated.json')).read_text()) for part in ['TRAIN','CALIBRATION','VALIDATION','VALIDATION_BENIGN']};parts['VALIDATION']+=parts.pop('VALIDATION_BENIGN');rr=parts['VALIDATION'];by={m:{x['run_id']:x for x in rr if x['method']==m} for m in METHODS+['H1','H2','H3']}
 allstats=[dict(partition=part,method=m,**stats([x for x in rows if x['method']==m])) for part,rows in parts.items() for m in METHODS];sums={x['method']:x for x in allstats if x['partition']=='VALIDATION'};d.h.write(O/'validation_summary.csv',allstats)
 sub=[dict(partition=part,method=m,subgroup=g,**stats([x for x in rows if x['method']==m and filt(x)])) for part,rows in parts.items() for m in METHODS for g,filt in FILTERS.items()];d.h.write(O/'subgroup_summary.csv',sub)
 pairs=[common.pair(rr,a,b,e) for a,b in [('A1','A0'),('A3','A0'),('A2','A0'),('A3','A1'),('A3','A2'),* [('A3',m) for m in METHODS if m.startswith('SVM')]] for e in ['fault','benign']];d.h.write(O/'paired_statistics.csv',pairs);d.h.write(O/'benign_paired_summary.csv',[x for x in pairs if x['endpoint']=='benign']);d.h.write(O/'svm_comparison.csv',[s for s in allstats if s['method'].startswith('SVM') or s['method']=='A3'])
 loc=[dict(method=m,origin=origin,**stats([x for x in rr if x['method']==m and (origin=='ALL' or x['origin']==origin)])) for m in ['A0','A1','A2','A3'] for origin in ['ALL',*d.r.be.ORIGINS,'NORMAL']];d.h.write(O/'localization_summary.csv',loc)
 gains={};lost={};gainrows=[];overlap=collections.Counter()
 for method,base in [('A1','A0'),('A3','A0'),('A3','A2')]:
  g=[x for k,x in by[method].items() if x['detected'] and not by[base][k]['detected']];gains[method+'_vs_'+base]=[x['run_id'] for x in g];lost[method+'_vs_'+base]=[k for k,x in by[base].items() if x['detected'] and not by[method][k]['detected']]
  for x in g:
   v=np.load(B/'tapes'/(x['run_id']+'_evaluated.npz'))['output'];i=int(np.flatnonzero(v[:,0]==x['first_post_alarm_ms'])[0]);hyp=[int(by['H'+str(j)][x['run_id']]['detected'] and not by['A2'][x['run_id']]['detected']) for j in [1,2,3]]
   record=dict(comparison=method+'_vs_'+base,run_id=x['run_id'],origin=x['origin'],domain=x['domain'],kind=x['kind'],magnitude=x['magnitude'],duration_ms=x['duration_ms'],first_origin=x['origin_at_alarm'],plant=x['plant_manifestation'],H1_detect=hyp[0],H2_detect=hyp[1],H3_detect=hyp[2],H1_score=v[i,1],H2_score=v[i,2],H3_score=v[i,3],H1_p=v[i,4],H2_p=v[i,5],H3_p=v[i,6],combined=v[i,7],mass=v[i,8],H1_mass_at_alarm=v[i,9],H2_mass_at_alarm=v[i,10],H3_mass_at_alarm=v[i,11],H1_onset_ms=int(v[i,12]),H2_onset_ms=int(v[i,13]),H2_end_ms=int(v[i,14]),H3_window=int(v[i,15]))
   gainrows.append(record)
   if method=='A1':overlap[''.join(map(str,hyp))]+=1
 d.h.write(O/'hypothesis_gain_summary.csv',gainrows or [dict(comparison='A1_vs_A0',note='No additional CP detections')])
 memory=[]
 for a,b in [('A2','A0'),('A3','A1')]:
  for group in ['effective_memory','dormant_memory']:
   keys=[k for k,x in by[b].items() if FILTERS[group](x)];memory.append(dict(comparison=a+'_vs_'+b,group=group,cases=len(keys),before=sum(by[b][k]['detected'] for k in keys),after=sum(by[a][k]['detected'] for k in keys),gained=sum(by[a][k]['detected'] and not by[b][k]['detected'] for k in keys),lost=sum(by[b][k]['detected'] and not by[a][k]['detected'] for k in keys),benign_alarm_delta=sums[a]['benign_false_alarms']-sums[b]['benign_false_alarms']))
 d.h.write(O/'memory_summary.csv',memory)
 a=sums['A3'];base=sums['A0'];critical={o:all(not x['detected'] or by['A3'][k]['detected'] for k,x in by['A0'].items() if x['origin']==o and (o!='MEMORY' or x['effective_memory_corruption'])) for o in ['MEMORY','TIMING','COMMUNICATION']}
 faultstats={m:stats([x for x in by[m].values() if x['injected']]) for m in ['A0','A3']}
 incremental={aa+'_vs_'+bb:sum(x['false_alarm'] and not by[bb][k]['false_alarm'] for k,x in by[aa].items()) for aa,bb in [('A1','A0'),('A3','A2')]}
 gate=dict(gain_ge_2pp=a['coverage']-base['coverage']>=.02-1e-12,no_cp_losses=not lost['A1_vs_A0'] and not lost['A3_vs_A2'],incremental_benign_le_005=all(x<=6 for x in incremental.values()) and a['benign_false_alarms']-base['benign_false_alarms']<=6,zero_wrong_fault_origins=a['wrong_confident_fault_runs']==0,plant_ge_97=a['coverage_given_plant_manifestation']>=.97,first_localized_accuracy_ge_999=a['accuracy_when_localized']>=.999,unknown_increase_le_5pp=base['localization_coverage']-a['localization_coverage']<=.05+1e-12,**{o+'_preserved':v for o,v in critical.items()})
 promote=all(gate.values()) and bool(gains['A1_vs_A0']) and json.loads((B/'selected_cp.json').read_text())['cal_gate_passed'];retained='CHANGE-POINT+MEMORY' if promote else 'MEMORY'
 strongest=max([m for m in METHODS if m.startswith('SVM') and m.endswith('default')],key=lambda m:sums[m]['detected']);matched=max([m for m in METHODS if m.startswith('SVM') and m.endswith('matched')],key=lambda m:sums[m]['detected']);additional=max(0,sums[strongest]['detected']-a['detected']+1)
 report=dict(overall=sums,promotion_gate=gate,cp_promoted=bool(promote),retained=retained,gains=gains,lost=lost,paired=pairs,memory=memory,hypothesis_overlap=dict(overlap),incremental_benign=incremental,strongest_default=strongest,strongest_matched=matched,additional_to_exceed_svm=additional,strong_success=a['detected']>sums[strongest]['detected'] and a['benign_false_alarm_rate']<=.015,very_strong_success=a['detected']>sums[strongest]['detected'] and a['benign_false_alarm_rate']<=.01 and a['coverage_given_plant_manifestation']>=.99 and a['wrong_confident_fault_runs']==0,both_actual_le_1pct=a['benign_false_alarm_rate']<=.01 and sums[matched]['benign_false_alarm_rate']<=.01,first_unknown=a['detected']-a['localized'],fault_runtime=faultstats['A3'],subgroups=[s for s in sub if s['partition']=='VALIDATION' and s['method']=='A3'])
 d.dump(B/'report.json',report)
 payload=lambda path:dict(encoding='zlib+base85; trusted local artifact',sha256=d.sha(path),data=base64.b85encode(zlib.compress(path.read_bytes())).decode())
 threshold_record=dict(primary=json.loads((B/'selected_cp.json').read_text()),tail=json.loads((B/'tail_calibration.json').read_text()),mapping=json.loads((B/'mapping_grid.json').read_text()),svm=json.loads((B/'svm_selection.json').read_text()),registration=json.loads((B/'registration.json').read_text()),validation_lock=json.loads((B/'lock.json').read_text()),manifest=json.loads((B/'specs.json').read_text()),overlap_audit=list(csv.DictReader((B/'historical_overlap_audit.csv').open())),report=report,models={space:payload(B/('svm_'+space+'.pkl')) for space in ['X','CP']},cdf_model=payload(B/'cdf.npz'))
 d.dump(O/'change_point_calibration.json',threshold_record)
 lines=['# Causal change-point findings','',f'Retained architecture: {retained}. CP promotion: {promote}.',f'Gate: {json.dumps(gate)}.','', '| Method | Detection | Wilson95% | Benign (Wilson95%) | Plant | Precision | Median/P95 ms |','|---|---|---|---|---|---|---|']
 for m,s in sums.items():lines.append(f"| {m} | {s['detected']}/{s['faulty_runs']} | {100*s['ci_low']:.2f}–{100*s['ci_high']:.2f}% | {s['benign_false_alarms']}/{s['benign_runs']} ({100*s['benign_ci_low']:.2f}–{100*s['benign_ci_high']:.2f}%) | {s['plant_detected']}/{s['plant_manifestation_runs']} | {s['precision']:.5f} | {s['latency_median_ms']}/{s['latency_p95_ms']} |")
 lines+=['',f"CP incremental A1/A0: {len(gains['A1_vs_A0'])}; A3/A2: {len(gains['A3_vs_A2'])}. Losses: {lost}. Incremental benign: {incremental}. Memory: {json.dumps(memory)}.",'',f'Hypothesis-only replay overlap H1/H2/H3 bitmask (000 means requires combined evidence or different temporal interaction): {dict(overlap)}. Isolated hypotheses use the frozen combination threshold and full multiplicity; they are explanatory ablations, not optimized separate detectors. H1/H2/H3 scores and winning temporal metadata at first additional alarm are in hypothesis_gain_summary.csv. H-only replays include250ms memory; sensor gains are unaffected by that separate channel.', '',f"First UNKNOWN: {report['first_unknown']}/{a['detected']}; first accuracy among localized {a['accuracy_when_localized']}. Runtime FAULT localized accuracy {faultstats['A3']['runtime_accuracy_among_localized']}. No new confident origin from CP; C/AB remains ambiguous. Benign wrong-origin samples are reported separately in NORMAL localization rows.",'',f"Strongest default: {strongest}. Additional A3 detections needed to exceed it: {additional}. Strongest CAL≤1% model: {matched}; BOTH actual≤1%: {report['both_actual_le_1pct']}. Do not describe the latter as matched if false. SVM feature sets include all legitimate cross-layer evidence; descriptive comparator parity transforms do not enable the rejected evidence provider.",'','The same unchanged physical runs feed all methods. Whitened change scores can also respond to legal offsets; run-level calibration budgets this collision. Equal ABC common-mode shifts lack an independent absolute reference. Unexcited-throughout actuator performance degradation remains physically unobservable. No validation tuning; no unseen. Covariance/model/protocol/manifest/source locks and overlap audit are embedded in change_point_calibration.json. CIs and exact McNemar are descriptive for grouped deterministic cases.','', 'Regression/integrity/overhead status is appended after targeted checks.']
 (O/'findings.md').write_text('\n'.join(lines)+'\n');print('REPORT',retained,gate,'GAINS',{k:len(v) for k,v in gains.items()},flush=True)
if __name__=='__main__':generate()
